function readyCount(unit=null,mine=false){let initial=mine?18:unit?([90,80,70][units.indexOf(unit)]||0):240;for(let r of state.rows){if((unit&&r.unit!==unit)||(mine&&r.owner!=='สมใจ'))continue;let original=base.find(b=>b.id===r.id);initial+=(r.status==='พร้อมสรุป'?1:0)-(original?.status==='พร้อมสรุป'?1:0)}return initial}
