function stat(label,value,unit,note,icon,featured=false,action=''){return `<button class="stat ${featured?'featured':''}" onclick="${action||'openSummary()'}"><div class="stat-top">${label}<span class="stat-icon">${I(icon)}</span></div><div class="stat-value">${value}<span>${unit}</span></div><div class="stat-note">${featured?I('check'):''}${note}</div></button>`}
function lineChart(){let own=state.dash==='mine',unit=state.dash==='unit';let values=own?[9,12,10,15,14,18]:unit?[54,62,58,73,78,90]:[152,178,165,210,218,240];if(unit&&units.indexOf(state.unit)!==0)values=values.map(v=>Math.round(v*(readyCount(state.unit)/90)));values[5]=readyCount(unit?state.unit:null,own);let max=own?Math.max(20,values[5]):unit?Math.max(100,values[5]):Math.max(300,values[5]);let points=values.map((v,i)=>`${48+i*96},${185-v/max*158}`);return `<div class="chart"><svg viewBox="0 0 570 220" role="img" aria-label="กราฟจำนวนกิจกรรม เมษายนถึงกันยายน ${values.join(', ')} กิจกรรม"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#238d79" stop-opacity=".14"/><stop offset="100%" stop-color="#238d79" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="48" x2="530" y1="${185-i*53}" y2="${185-i*53}" stroke="#edf0f4" stroke-dasharray="3 4"/><text x="27" y="${189-i*53}" text-anchor="end">${Math.round(max*i/3)}</text>`).join('')}<path d="M48 185 L${points.join(' L')} L528 185Z" fill="url(#fade)"/><polyline points="${points.join(' ')}" fill="none" stroke="#278877" stroke-width="2.7"/>${points.map((p,i)=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="3.5" fill="#fff" stroke="#278877" stroke-width="2"/><text x="${p.split(',')[0]}" y="${+p.split(',')[1]-12}" text-anchor="middle" style="fill:#52776c;font-size:10px">${values[i]}</text>`).join('')}${['เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.'].map((m,i)=>`<text x="${48+i*96}" y="210" text-anchor="middle">${m} 69</text>`).join('')}</svg></div>`}
function donut(){let overview=state.dash==='overview',mine=state.dash==='mine';let vals=overview?units.map(u=>readyCount(u)):mine?[6,8,Math.max(0,readyCount(null,true)-14)]:units.indexOf(state.unit)===0?[30,40,Math.max(0,readyCount(state.unit)-70)]:[readyCount(state.unit),0,0];let labels=overview?units.map(u=>u.replace('ฝ่าย','')):(state.dash==='unit'&&units.indexOf(state.unit)!==0?[state.unit.replace('ฝ่าย',''),'ประเภทอื่น','ยังไม่ระบุ']:['ประชุมและอบรม','ส่งเสริมสุขภาพ','เยี่ยมบ้าน']);let total=vals.reduce((a,b)=>a+b,0),offset=0;let colors=['#258476','#6b9eb7','#d8b66e'];return `<div class="donut-body"><div class="donut"><svg viewBox="0 0 160 160" role="img" aria-label="สัดส่วนกิจกรรม"><circle cx="80" cy="80" r="63" fill="none" stroke="#f3f5f7" stroke-width="20"/>${vals.map((v,i)=>{let dash=v/total*396;let s=`<circle cx="80" cy="80" r="63" fill="none" stroke="${(colors[i%3])}" stroke-width="20" stroke-dasharray="${Math.max(0,dash-4)} ${400-dash+4}" stroke-dashoffset="${-offset}"/>`;offset+=dash;return s}).join('')}</svg><div class="donut-label"><strong>${total}</strong><small>กิจกรรมทั้งหมด</small></div></div><div class="donut-legend">${labels.map((l,i)=>`<div class="item"><i style="background:${(colors[i%3])}"></i>${l}<b>${vals[i]}</b></div>`).join('')}<div style="font-size:9px;color:#9aa4b0;border-top:1px solid var(--line);padding-top:12px">หน่วยนับ: กิจกรรม</div></div></div>`}
function dashboard(){let mine=state.dash==='mine',unit=state.dash==='unit';let titles={overview:'ภาพรวมสำนัก',mine:'ข้อมูลที่ฉันนำเข้า',unit:state.unit};let empty=state.month!=='กันยายน 2569';let ready=readyCount(unit?state.unit:null,mine);let added=0;return headline(titles[state.dash],'ภาพรวมข้อมูลการปฏิบัติงาน เพื่อเชื่อมโยงข้อมูลและขับเคลื่อนสุขภาวะเมือง',btn('นำเข้าข้อมูล',"state.step=1;go('import')",'plus',true))+tabs([['overview','ภาพรวมสำนัก'],['unit','ข้อมูลหน่วยงาน'],['mine','ข้อมูลที่ฉันนำเข้า']],state.dash,'setDash')+`<div class="filters">${select(['กันยายน 2569','สิงหาคม 2569','กรกฎาคม 2569'],state.month,"state.month=this.value;render()",'calendar')}${unit?select(units,state.unit,"state.unit=this.value;render()",'building'):select(['ทุกหน่วยงาน',...units],'ทุกหน่วยงาน',"state.unit=this.value;state.dash=this.value==='ทุกหน่วยงาน'?'overview':'unit';render()",'building')}<span class="update">${I('clock')}อัปเดตล่าสุด 30 ก.ย. 2569 เวลา 09:30 น.</span></div>${empty?`<div class="panel empty">${I('folder')}<h2>ยังไม่มีข้อมูลในช่วงเวลานี้</h2><p>ข้อมูลจำลองที่เชื่อมโยงกันอยู่ในเดือนกันยายน 2569</p>${btn('ดูข้อมูลเดือนกันยายน',"state.month='กันยายน 2569';render()")}</div>`:`<div class="stats">${stat(mine?'รายการงานที่พร้อมสรุป':unit?'กิจกรรมที่พร้อมสรุป':'กิจกรรมที่รายงานทั้งสำนัก',ready+added,'กิจกรรม','พร้อมสรุปจากข้อมูลที่ตรวจแล้ว','activity',true)}${stat(mine?'รายการรอตรวจข้อมูล':unit?'รายการรอตรวจข้อมูล':'หน่วยงานที่มีข้อมูล',mine?pendingCount(null,true):unit?pendingCount(state.unit):units.length,mine||unit?'รายการ':'ฝ่าย',mine||unit?'ยังไม่รวมในยอดกิจกรรม':'ข้อมูลจาก 3 ฝ่ายในชุดข้อมูลจำลอง',mine||unit?'clock':'building',false,mine||unit?"openSummary('รอตรวจข้อมูล')":"setDash('unit')")}${stat(mine?'ไฟล์ที่ฝากเก็บ':'แหล่งข้อมูลที่เชื่อมโยง',mine?state.docs.length:2,mine?'ไฟล์':'ช่องทาง',mine?'จัดเก็บเพื่อค้นหา ไม่รวมในกิจกรรม':'<b>LINE</b> และอัปโหลดผ่านเว็บ','folder',false,"state.tab='ไฟล์';go('library')")}${stat('ช่วงเวลาของข้อมูล','ก.ย. 69','', '1 – 30 กันยายน 2569','calendar',false,"periodInfo()")}</div><div class="charts"><section class="panel"><div class="panel-head"><div><h2>แนวโน้ม${mine?'รายการงาน':'กิจกรรม'}รายเดือน</h2><p>จำนวนกิจกรรมที่พร้อมสรุป • เมษายน – กันยายน 2569</p></div><div class="legend"><i></i> กิจกรรม</div></div>${lineChart()}</section><section class="panel"><div class="panel-head"><div><h2>${state.dash==='overview'?'สัดส่วนกิจกรรมตามหน่วยงาน':'กิจกรรมแยกตามประเภทงาน'}</h2><p>ประจำเดือนกันยายน 2569</p></div><button aria-label="ข้อมูลกราฟ" onclick="periodInfo()">${I('info')}</button></div>${donut()}</section></div>${state.dash==='overview'?unitTable():`<section class="panel"><div class="table-head"><div><h2>${mine?'ข้อมูลที่นำเข้าล่าสุด':'รายการงานและผลการดำเนินงาน'}</h2><p>แสดงรายการตัวอย่างจาก${mine?'ข้อมูลที่คุณนำเข้า':state.unit}</p></div><button class="text-btn" onclick="openSummary()">ดูทั้งหมด ${I('arrow')}</button></div>${workTable(state.rows.filter(r=>mine?r.owner==='สมใจ':r.unit===state.unit).slice(0,4))}</section>`}<div class="notice">${I('info')}<div><b>เกี่ยวกับการนับข้อมูล</b> &nbsp; จำนวนกิจกรรมนับจากรายการงาน ไม่ใช่จำนวนข้อความ รูปภาพ หรือไฟล์แนบ รายการรอตรวจและไฟล์ที่ฝากเก็บยังไม่รวมในยอดสรุป<br>ผลการดำเนินงาน เช่น คน ครั้งบริการ และตัน แสดงแยกตามหน่วยนับ โดยไม่รวมยอดต่างหน่วยเข้าด้วยกัน</div></div>`}`}
function unitTable(){return `<section class="panel"><div class="table-head"><div><h2>สรุปผลการปฏิบัติงานตามหน่วยงาน</h2><p>ข้อมูลที่พร้อมสรุป ประจำเดือนกันยายน 2569</p></div><span class="badge neutral">${units.length} หน่วยงาน</span></div><div class="table-wrap"><table><thead><tr><th style="width:34%">หน่วยงาน</th><th>กิจกรรมที่พร้อมสรุป</th><th>ผลการดำเนินงานสำคัญ</th><th>สถานะข้อมูล</th><th></th></tr></thead><tbody>${units.map((u,i)=>`<tr><td><div class="unit-cell"><span class="unit-icon ${['','blue','gold'][i]}">${I(['heart','shield','leaf'][i]||'building')}</span><div><strong>${u}</strong><small>สำนักสาธารณสุขและสิ่งแวดล้อม</small></div></div></td><td><strong>${readyCount(u)}</strong> <span class="muted" style="font-size:10px">กิจกรรม</span></td><td>${['ประชุมเครือข่าย อสม. 32 คน','สำรวจพื้นที่ 60 หลังคาเรือน','จัดเก็บขยะ 2.4 ตัน'][i]||'ไม่พบข้อมูล'}<small>ตัวอย่างผลรายกิจกรรม · ไม่ใช่ยอดรวมฝ่าย</small></td><td>${badge(pendingCount(u)?'รอตรวจ '+pendingCount(u)+' รายการ':'พร้อมสรุป')}</td><td><button class="text-btn" onclick="state.unit=units[${i}];setDash('unit')">ดูแดชบอร์ด ${I('chevron')}</button></td></tr>`).join('')}<tr class="total"><td>รวมกิจกรรมทั้งสำนัก</td><td>${readyCount()} กิจกรรม</td><td colspan="3" style="font-weight:400;color:#8993a0">รวมเฉพาะหน่วยนับกิจกรรม ไม่รวมผลที่มีหน่วยนับต่างกัน</td></tr></tbody></table></div></section>`}
function openSummary(status=''){state.query='';state.statusFilter=status;state.libraryUnit=state.dash==='unit'?state.unit:'ทุกหน่วยงาน';state.scope=state.dash==='mine'?'ข้อมูลที่ฉันนำเข้า':'ทั้งหมด';state.tab='งาน';go('library')}
function workTable(rows){if(!rows.length)return `<div class="empty">${I('search')}<h2>ไม่พบข้อมูลที่ตรงกับการค้นหา</h2><p>ลองเปลี่ยนคำค้นหาหรือล้างตัวกรอง</p>${btn('ล้างตัวกรอง','resetFilters()')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>ชื่องาน / วันที่ปฏิบัติงาน</th><th>หน่วยงาน / พื้นที่</th><th>ผลและหน่วยนับ</th><th>แหล่งที่มา</th><th>สถานะ</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button style="text-align:left;padding:0" onclick="detail(${r.id})"><strong>${esc(r.name)}</strong><small>${esc(r.date)} · ${esc(r.type)}</small></button></td><td>${esc(r.unit)}<small>${esc(r.area)}</small></td><td>${esc(r.result)}</td><td>${badge(r.source)}</td><td>${badge(r.status)}</td><td><button aria-label="เปิด ${esc(r.name)}" class="text-btn" onclick="detail(${r.id})">${I('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`}
function resetFilters(){state.query='';state.source='ทั้งหมด';state.type='ทั้งหมด';state.scope='ทั้งหมด';state.libraryUnit='ทุกหน่วยงาน';state.statusFilter='';state.month='กันยายน 2569';state.pageNum=1;render()}
function library(){let rows=state.rows.filter(r=>(!state.query||[r.name,r.area,r.type].join(' ').includes(state.query))&&(!state.libraryUnit||state.libraryUnit==='ทุกหน่วยงาน'||r.unit===state.libraryUnit)&&(state.source==='ทั้งหมด'||r.source===state.source)&&(state.type==='ทั้งหมด'||r.type===state.type)&&(state.scope==='ทั้งหมด'||r.owner==='สมใจ')&&(!state.statusFilter||r.status===state.statusFilter)&&state.month==='กันยายน 2569');let docs=state.docs.filter(r=>(!state.query||r.name.includes(state.query))&&(!state.libraryUnit||state.libraryUnit==='ทุกหน่วยงาน'||r.unit===state.libraryUnit)&&state.month==='กันยายน 2569'&&(state.source==='ทั้งหมด'||state.source==='อัปโหลดผ่านเว็บ'));let list=state.tab==='งาน'?rows:docs;let n=5;return headline('คลังข้อมูล','ค้นหางาน เอกสาร และหลักฐานต้นทางที่เชื่อมโยงไว้ในที่เดียว',btn('นำเข้าข้อมูล',"state.step=1;go('import')",'plus',true))+tabs([['งาน','รายการงาน'],['ไฟล์','ไฟล์และเอกสาร']],state.tab,'setTab')+`<div class="filters"><label class="filter">${I('search')}<input aria-label="ค้นหาชื่องาน เอกสาร หรือคำสำคัญ" placeholder="ค้นหาชื่องาน เอกสาร หรือคำสำคัญ" value="${esc(state.query)}" oninput="searchInput(this)"></label>${select(['ทุกหน่วยงาน',...units],state.libraryUnit||'ทุกหน่วยงาน',"state.libraryUnit=this.value;state.pageNum=1;render()",'building')}${select(['กันยายน 2569','สิงหาคม 2569'],state.month,"state.month=this.value;render()",'calendar')}${select(['ทั้งหมด','LINE','อัปโหลดผ่านเว็บ'],state.source,"state.source=this.value;render()")}${select(['ทั้งหมด','ประชุมและอบรม','กิจกรรมส่งเสริมสุขภาพ','เยี่ยมบ้าน'],state.type,"state.type=this.value;render()")}${select(['ทั้งหมด','ข้อมูลที่ฉันนำเข้า'],state.scope,"state.scope=this.value;render()",'people')}${btn('ล้างตัวกรอง','resetFilters()')}</div><section class="panel"><div class="table-head"><h2>${state.tab==='งาน'?'รายการงาน':'ไฟล์และเอกสาร'} <span class="muted" style="font-size:12px;font-weight:400">${list.length} รายการตัวอย่าง</span></h2>${state.statusFilter?badge(state.statusFilter):'<span class="muted" style="font-size:11px">กันยายน 2569</span>'}</div>${state.tab==='งาน'?workTable(rows.slice((state.pageNum-1)*n,state.pageNum*n)):docs.length?`<div class="table-wrap"><table><thead><tr><th>ชื่อไฟล์</th><th>ประเภท</th><th>หน่วยงาน</th><th>ผู้นำเข้า / วันที่</th><th>วัตถุประสงค์</th></tr></thead><tbody>${docs.slice((state.pageNum-1)*n,state.pageNum*n).map(d=>`<tr><td><button class="text-btn" onclick="previewDoc('${esc(d.name)}')">${I('file')}${esc(d.name)}</button></td><td>${d.type}</td><td>${esc(d.unit)}</td><td>${esc(d.owner)}<small>${d.date}</small></td><td>${badge('ฝากเก็บ')}<small>อัปโหลดผ่านเว็บ</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">ไม่พบไฟล์และเอกสาร</div>'}<div class="table-footer"><span>แสดง ${list.length?((state.pageNum-1)*n+1):0}–${Math.min(state.pageNum*n,list.length)} จาก ${list.length} รายการตัวอย่าง</span><div class="pages">${Array.from({length:Math.max(1,Math.ceil(list.length/n))},(_,i)=>`<button class="${state.pageNum===i+1?'active':''}" onclick="state.pageNum=${i+1};render()">${i+1}</button>`).join('')}</div></div></section><div class="notice">${I('info')}คลังนี้แสดงรายละเอียดบางรายการเพื่อสาธิต ส่วนยอดแดชบอร์ดเป็นข้อมูลจำลองสรุปทั้งเดือน • รายงานจาก LINE เข้าสู่คลังโดยตรง ไม่ต้องอัปโหลดซ้ำ</div>`}
function searchInput(el){let pos=el.selectionStart;state.query=el.value;state.pageNum=1;render();let input=$('input[aria-label="ค้นหาชื่องาน เอกสาร หรือคำสำคัญ"]');input.focus();input.setSelectionRange(pos,pos)}
function detail(id){state.selected=id;go('detail')}
function editable(r){return (state.roles.includes('เจ้าหน้าที่ปฏิบัติงาน')&&r.owner==='สมใจ')||(state.roles.includes('หัวหน้าฝ่าย')&&r.unit===units[0])}
function detailPage(){let r=state.rows.find(x=>x.id===state.selected),edit=editable(r),dis=edit?'':'disabled';return headline('รายละเอียดและตรวจแก้ข้อมูล','เชื่อมโยงข้อมูลที่สกัดได้กับหลักฐานต้นทาง ตรวจสอบย้อนกลับได้',btn('กลับไปคลังข้อมูล',"go('library')",'folder'))+`<div class="filters">${badge(r.status)}${badge(r.source)}<span class="badge neutral">${edit?'คุณมีสิทธิ์แก้ไขรายการนี้':'อ่านอย่างเดียว • ไม่มีสิทธิ์แก้ไข'}</span><span class="update">${I('clock')}แก้ไขล่าสุด 18 ก.ย. 2569 · สมใจ ใจดี</span></div><div class="split"><section class="panel"><div class="table-head"><h2>หลักฐานต้นทาง</h2><button class="text-btn" onclick="sourceModal()">เปิดต้นฉบับ ${I('link')}</button></div><div class="source"><div class="source-label">${r.id===1?'LINE · กลุ่มรายงานงานส่งเสริมสุขภาพ':'ข้อมูลต้นทางตัวอย่าง'}<br>ผู้รายงาน / ผู้นำเข้า: ${esc(r.owner)} ใจดี</div><div class="message">${r.id===1?'วันนี้ 18 กันยายน 2569 จัดประชุมเครือข่าย อสม. ที่ชุมชนตัวอย่างค่ะ':esc(r.name)}<br><small class="muted">09:10 น.</small></div><div class="message">${esc(r.result)}<br><small class="muted">09:12 น.</small></div><div class="message">${r.id===1?'ผู้ปฏิบัติงาน: นางสมใจ ใจดี และเครือข่าย อสม. แนบภาพกิจกรรมทั้งหมด 10 รูปค่ะ':esc(r.workers)}<br><small class="muted">09:15 น.</small></div><div class="evidence">${Array.from({length:r.id===1?10:3},(_,i)=>`<button onclick="imageModal(${i%3})" aria-label="ดูภาพหลักฐาน ${i+1}"><img src="${photos[i%3]}" alt="ภาพประกอบหลักฐานจำลอง ${i+1}" loading="lazy"></button>`).join('')}</div><p class="source-label">ภาพประกอบเพื่อสาธิต ไม่ใช่ภาพกิจกรรมจริง</p></div><div class="body-pad"><div class="notice" style="margin:0">${I('info')} ${r.id===1?'3 ข้อความ + 10 รูปภาพ = 1 กิจกรรม':'นับเป็น 1 กิจกรรมเมื่อข้อมูลพร้อมสรุป'}<br>หลักฐานหลายรายการถูกเชื่อมกับงานเดียวกัน</div></div></section><section class="panel"><div class="table-head"><h2>ข้อมูลรายการงาน</h2><span class="badge neutral">AI ช่วยจัดข้อมูล</span></div><form class="form body-pad" onsubmit="saveReport(event)"><label>ชื่องาน<input name="name" value="${esc(r.name)}" required ${dis}></label><div class="row"><label>วันที่ปฏิบัติงาน<input name="date" value="${esc(r.date)}" required ${dis}></label><label>หน่วยงาน<select name="unit" ${dis}>${opts(units,r.unit)}</select></label></div><div class="row"><label>ประเภทงาน<input name="type" value="${esc(r.type)}" required ${dis}></label><label>พื้นที่ ${r.area==='ไม่พบข้อมูล'?badge('รอตรวจสอบ'):''}<input name="area" value="${r.area==='ไม่พบข้อมูล'?'':esc(r.area)}" placeholder="ไม่พบข้อมูล" required ${dis}></label></div><label>ผู้ปฏิบัติงานตามข้อมูลต้นทาง<input name="workers" value="${r.workers==='ไม่พบข้อมูล'?'':esc(r.workers)}" placeholder="ไม่พบข้อมูล" required ${dis}></label><label>ผลการดำเนินงาน<textarea name="result" required ${dis}>${esc(r.result)}</textarea></label><div class="row"><label>ตัวเลข<input name="number" type="number" min="0" step="any" value="${r.number}" required ${dis}></label><label>หน่วยนับ<select name="measure" ${dis}>${opts(['คน','ครั้งบริการ','ตัน','หลังคาเรือน','ครั้ง'],r.measure)}</select></label></div><label>สถานะข้อมูล<select name="status" ${dis}>${opts(['พร้อมสรุป','รอตรวจข้อมูล'],r.status)}</select></label><div class="notice" style="margin:0">${I('info')}ผู้นำเข้า: ${esc(r.owner)} ใจดี • แยกจากผู้ปฏิบัติงานตามต้นทาง<br>รายการที่ชัดเจนพร้อมสรุปได้ โดยไม่ต้องให้หัวหน้าอนุมัติทุกครั้ง</div>${edit?'<button class="btn primary" type="submit">บันทึกการแก้ไข</button>':'<p class="subtitle">ทุกคนดูข้อมูลได้ การแก้ไขจำกัดตามเจ้าของและฝ่ายที่รับผิดชอบ</p>'}</form></section></div>`}
function saveReport(e){e.preventDefault();let r=state.rows.find(x=>x.id===state.selected);if(!editable(r))return toast('ไม่มีสิทธิ์แก้ไขรายการนี้');let data=Object.fromEntries(new FormData(e.target));let old=r.result;Object.assign(r,data);audit(r.name,'แก้ไขข้อมูล',old,r.result);persist();state.dash='mine';go('dashboard');toast('บันทึกการแก้ไขแล้ว • อัปเดตข้อมูลที่ฉันนำเข้า')}
function importPage(){return headline('นำเข้าข้อมูล','เลือกเก็บเอกสารเพื่ออ้างอิง หรือจัดข้อมูลเป็นรายการงานเพื่อสรุปผลงาน')+`<div class="stepper">${['เลือกไฟล์','เลือกวัตถุประสงค์','ตรวจข้อมูลและบันทึก'].map((s,i)=>`<div class="step ${state.step===i+1?'active':''}"><span>${i+1}</span>${s}</div>`).join('')}</div><section class="panel body-pad" style="max-width:850px;margin:auto">${state.step===1?`<div class="drop" ondragover="event.preventDefault();this.style.background='#e6f4ef'" ondragleave="this.style.background=''" ondrop="event.preventDefault();chooseFiles(event.dataTransfer.files)">${I('upload')}<h3>ลากไฟล์มาวางที่นี่</h3><p>รองรับ PDF, Excel และรูปภาพ • สูงสุด 20 MB ต่อไฟล์</p><input id="fileInput" type="file" accept=".pdf,.xlsx,.xls,.jpg,.jpeg,.png" multiple hidden onchange="chooseFiles(this.files)">${btn('เลือกไฟล์จากเครื่อง',"$('#fileInput').click()",'plus',true)}</div><p class="subtitle" style="text-align:center;margin:18px">หรือ ${btn('ใช้ไฟล์ตัวอย่าง',"state.files=[{name:'รายงานกิจกรรมสุขภาพ_กันยายน.pdf',size:245000,type:'PDF'}];render()")}</p>${state.files.map((f,i)=>`<div class="choice" style="padding:13px;margin-bottom:9px">${I('file')}<span style="flex:1">${esc(f.name)}<small class="muted"> · ${Math.round(f.size/1024)} KB</small></span><button aria-label="ลบไฟล์" onclick="state.files.splice(${i},1);render()">${I('close')}</button></div>`).join('')}<div class="actions" style="justify-content:flex-end;margin-top:20px">${btn('ถัดไป',"if(state.files.length){state.step=2;render()}else toast('กรุณาเลือกไฟล์ก่อนดำเนินการต่อ')",'arrow',true)}</div>`:state.step===2?`<h2 style="margin-bottom:20px">ต้องการใช้ไฟล์นี้เพื่ออะไร?</h2><div class="form"><button class="choice ${state.purpose==='archive'?'selected':''}" onclick="state.purpose='archive';render()">${I('folder')}<div><h3>ฝากไฟล์ไว้ค้นหาและอ้างอิง</h3><p>จัดเก็บเอกสารส่วนกลาง ค้นหาและเปิดดูได้<br>ไฟล์จะไม่ถูกนับเป็นกิจกรรม</p></div></button><button class="choice ${state.purpose==='report'?'selected':''}" onclick="state.purpose='report';render()">${I('activity')}<div><h3>จัดข้อมูลเพื่อนำไปสรุปผลงาน</h3><p>AI ช่วยสกัดข้อมูลเป็นรายการงาน ให้คุณตรวจสอบและแก้ไข<br>รวมยอดเมื่อข้อมูลพร้อมสรุป</p></div></button></div><div class="actions" style="justify-content:space-between;margin-top:25px">${btn('ย้อนกลับ',"state.step=1;render()")}${btn('ถัดไป',"nextImport()",'arrow',true)}</div>`:state.processing?`<div class="empty">${I('clock')}<h2>กำลังประมวลผล</h2><p>กำลังจัดข้อมูลจาก ${state.files.length} ไฟล์ กรุณารอสักครู่…</p></div>`:state.purpose==='archive'?`<h2 style="margin-bottom:20px">รายละเอียดเอกสาร</h2><form class="form" onsubmit="saveArchive(event)"><label>ชื่อเอกสาร<input name="name" value="${esc(state.files[0]?.name)}" required></label><div class="row"><label>หน่วยงาน<select name="unit">${opts(units,units[0])}</select></label><label>หมวดข้อมูล<select name="category">${opts(['เอกสารอ้างอิง','รายงานการประชุม','ภาพประกอบ'],'เอกสารอ้างอิง')}</select></label></div><label>คำสำคัญ<input name="keywords" placeholder="เช่น สุขภาพ, กันยายน, อสม."></label><div class="notice">${I('info')}เอกสารนี้จะปรากฏในคลังไฟล์ และไม่ถูกนับเป็นกิจกรรม</div><button class="btn primary" type="submit">บันทึกไฟล์เข้าคลัง</button></form>`:`<h2>ผลการจัดข้อมูล</h2><p class="subtitle" style="margin:8px 0 20px">ข้อมูลที่สกัดได้ยังไม่รวมในยอดสรุป กรุณาตรวจข้อมูลก่อน</p>${state.files.map(f=>`<div class="choice">${I('file')}<div style="flex:1">${esc(f.name)}<p>ไม่พบข้อมูลบางส่วน • ต้องตรวจวันที่ พื้นที่ และผลการดำเนินงาน</p></div>${badge('รอตรวจข้อมูล')}</div>`).join('')}<div class="actions" style="justify-content:flex-end;margin-top:24px">${btn('ตรวจข้อมูล','openImported()','edit',true)}</div>`}</section><div class="notice" style="max-width:850px;margin:20px auto">${I('info')}รายงานจาก LINE จะปรากฏในคลังข้อมูลพร้อมหลักฐาน เจ้าหน้าที่ไม่จำเป็นต้องนำเข้าไฟล์เดิมซ้ำ</div>`}
function chooseFiles(files){let valid=[];for(let f of files){if(!/\.(pdf|xlsx?|jpe?g|png)$/i.test(f.name)||f.size>20*1024*1024){modal('นำเข้าไม่สำเร็จ',`<p>ไฟล์ ${esc(f.name)} ไม่รองรับ หรือมีขนาดเกิน 20 MB</p><p>กรุณาเลือก PDF, Excel หรือรูปภาพ แล้วลองใหม่</p>`,btn('ลองใหม่',"closeModal();$('#fileInput').click()",'upload',true));return}valid.push({name:f.name,size:f.size,type:f.name.split('.').pop().toUpperCase()})}state.files=valid;render()}
function nextImport(){state.step=3;if(state.purpose==='report'){state.processing=true;render();setTimeout(()=>{state.processing=false;if(state.page==='import')render()},1200)}else render()}
function saveArchive(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));state.files.forEach((f,i)=>state.docs.push({...d,name:i===0?d.name:f.name,type:f.type||'PDF',owner:'สมใจ',date:'30 กันยายน 2569'}));audit(d.name,'เพิ่มเอกสาร','ไม่มีเอกสาร','ฝากไฟล์ไว้ค้นหาและอ้างอิง');persist();state.dash='mine';go('dashboard');toast('บันทึกไฟล์เข้าคลังเรียบร้อยแล้ว')}
function openImported(){if(!state.roles.includes('เจ้าหน้าที่ปฏิบัติงาน')){state.roles.push('เจ้าหน้าที่ปฏิบัติงาน');toast('เปิดบทบาทเจ้าหน้าที่สำหรับทดลองตรวจข้อมูลของตนเอง')}let r={id:Date.now(),name:state.files[0].name.replace(/\.[^.]+$/,''),date:'30 กันยายน 2569',unit:units[0],type:'กิจกรรมส่งเสริมสุขภาพ',area:'ไม่พบข้อมูล',workers:'ไม่พบข้อมูล',result:'รอตรวจสอบ',number:'',measure:'คน',source:'อัปโหลดผ่านเว็บ',status:'รอตรวจข้อมูล',owner:'สมใจ'};state.rows.push(r);persist();detail(r.id)}
function feed(){let items=[{title:'ร่วมสร้างเมืองสะอาด ใส่ใจสิ่งแวดล้อม',unit:units[2],date:'15 กันยายน 2569',area:'ตลาดเทศบาล',img:photos[2],body:'ฝ่ายบริการสิ่งแวดล้อมดำเนินการจัดเก็บขยะและปรับปรุงสภาพแวดล้อมในพื้นที่ตลาดเทศบาล จัดเก็บขยะจำนวน 2.4 ตัน เพื่อให้พื้นที่สาธารณะสะอาดและพร้อมให้บริการประชาชน'},{title:'ส่งเสริมสุขภาพผู้สูงอายุ ใกล้ชิดชุมชน',unit:units[0],date:'17 กันยายน 2569',area:'ชุมชนโนนทัน',img:photos[1],body:'ฝ่ายส่งเสริมสุขภาพจัดกิจกรรมส่งเสริมสุขภาพผู้สูงอายุ ณ ชุมชนโนนทัน มีผู้เข้าร่วม 45 คน'}];if(state.published)items.unshift({title:state.newsTitle,unit:units[0],date:'18 กันยายน 2569',area:'ชุมชนตัวอย่าง',img:photos[state.cover],body:state.newsBody});state.feedItems=items;items=items.filter(x=>(!state.feedUnit||state.feedUnit==='ทุกหน่วยงาน'||x.unit===state.feedUnit)&&state.month==='กันยายน 2569');return headline('ฟีดข่าวภายใน','เรื่องราวการทำงานและความเคลื่อนไหวจากหน่วยงานของเรา')+`<div class="filters">${select(['ทุกหน่วยงาน',...units],state.feedUnit||'ทุกหน่วยงาน',"state.feedUnit=this.value;render()",'building')}${select(['กันยายน 2569','สิงหาคม 2569'],state.month,"state.month=this.value;render()",'calendar')}<span class="update">${I('shield')}สำหรับผู้เข้าสู่ระบบภายในองค์กร</span></div><div class="cards">${items.map(x=>`<article class="panel news-card"><img src="${x.img}" alt="ภาพประกอบข่าวจำลอง"><div class="body-pad"><span class="badge neutral">${x.unit}</span><h2>${esc(x.title)}</h2><p>${esc(x.body.slice(0,120))}…</p><div class="news-meta"><span>${x.date}</span><span>${x.area}</span></div><button class="text-btn" style="margin-top:20px" onclick="readNews(${state.feedItems.indexOf(x)})">อ่านเพิ่มเติม ${I('arrow')}</button></div></article>`).join('')||'<div class="panel empty">ยังไม่มีข่าวที่เผยแพร่ในช่วงเวลานี้</div>'}</div><div class="notice">${I('info')}แสดงเฉพาะข่าวที่เจ้าหน้าที่ประชาสัมพันธ์ยืนยันเผยแพร่แล้ว • ภาพประกอบและเนื้อหาเป็นข้อมูลจำลอง</div>`}
function news(){let show=state.newsTab==='รอพิจารณา'?!state.published&&!state.rejected:state.newsTab==='ฉบับร่าง'?state.draft&&!state.published:state.published;return headline('จัดการข่าวประชาสัมพันธ์','พิจารณาข้อมูลต้นทาง ตรวจข้อความและรูปภาพ ก่อนเผยแพร่ภายในองค์กร',btn('เลือกรายงานเอง','pickReport()','plus',true))+tabs(['รอพิจารณา','ฉบับร่าง','เผยแพร่แล้ว'].map(x=>[x,x]),state.newsTab,'setNewsTab')+`<section class="panel">${show?`<div class="list-news"><img src="${photo}" alt="ภาพประกอบกิจกรรมจำลอง"><div class="news-info">${badge(state.manual?'เจ้าหน้าที่เลือก':'AI เสนอ')}<h3>ประชุมเครือข่าย อสม.</h3><p>ฝ่ายส่งเสริมสุขภาพ · 18 กันยายน 2569 · ชุมชนตัวอย่าง</p><p>จัดประชุม 1 ครั้ง • ผู้เข้าร่วม 32 คน</p></div><div class="actions">${btn('ดูต้นทาง','detail(1)','file')}${state.published?btn('ดูข่าว',"go('feed')",'eye'):btn('จัดทำข่าว',"go('editor')",'edit',true)}${!state.published?`<button class="text-btn" onclick="state.rejected=true;persist();render();toast('นำออกจากรายการเสนอข่าวแล้ว')">ไม่เลือกเป็นข่าว</button>`:''}</div></div>`:`<div class="empty">${I('news')}<h2>ไม่มีข่าวใน${state.newsTab}</h2><p>เลือกรายงานต้นทางเพื่อจัดทำข่าวได้</p>${btn('เลือกรายงานเอง','pickReport()','plus')}</div>`}</section><div class="notice">${I('info')}AI เสนอเฉพาะรายการที่เหมาะสำหรับพิจารณา ข่าวจะไม่ถูกเผยแพร่จนกว่าเจ้าหน้าที่ประชาสัมพันธ์จะตรวจและยืนยัน</div>`}
function editor(){return headline('ตรวจแก้และเผยแพร่ข่าว','ข่าวฉบับเผยแพร่แยกจากรายงานต้นฉบับ การแก้ข้อความไม่เปลี่ยนข้อมูลเจ้าของรายงาน',btn('ดูรายงานต้นฉบับ','detail(1)','link'))+`<div class="split"><section class="panel body-pad"><form class="form" id="newsForm" onsubmit="event.preventDefault();previewNews()"><label>หัวข้อข่าว<input id="newsTitle" value="${esc(state.newsTitle)}" required oninput="state.newsTitle=this.value"></label><label>เนื้อหาข่าว<textarea style="min-height:225px" id="newsBody" required oninput="state.newsBody=this.value">${esc(state.newsBody)}</textarea></label><div class="row"><label>วันที่กิจกรรม<input value="18 กันยายน 2569" readonly></label><label>หน่วยงาน<input value="ฝ่ายส่งเสริมสุขภาพ" readonly></label></div><label>พื้นที่<input value="ชุมชนตัวอย่าง" readonly></label><div class="actions">${btn('บันทึกฉบับร่าง',"saveDraft()",'file')}<button class="btn primary" type="submit">${I('eye')} Preview ก่อนเผยแพร่</button></div></form></section><section class="panel body-pad"><h2>เลือกรูปจากหลักฐาน</h2><p class="subtitle" style="margin:10px 0">คลิกรูปเพื่อเลือก / ยกเลิก และเลือกรูปปกด้านล่าง</p><div class="evidence">${photos.map((p,i)=>`<button class="${state.picked.includes(i)?'selected':''}" onclick="togglePhoto(${i})"><img src="${p}" alt="ภาพหลักฐานจำลอง ${i+1}"><span class="badge ${state.picked.includes(i)?'':'neutral'}">${state.picked.includes(i)?'เลือกรูปแล้ว':'เลือกรูป'}</span></button>`).join('')}</div><label class="filter" style="margin-top:20px">รูปปก <select onchange="state.cover=Number(this.value);render()">${state.picked.map(i=>`<option value="${i}" ${state.cover===i?'selected':''}>ภาพที่ ${i+1}</option>`).join('')}</select></label><img src="${photos[state.cover]}" alt="รูปปกข่าวจำลอง" style="width:100%;height:220px;object-fit:cover;margin-top:20px;border-radius:8px"><div class="notice">${I('info')}ภาพประกอบเพื่อสาธิต ไม่ใช่ภาพกิจกรรมจริง<br>การส่ง LINE ในโปรโตไทป์เป็นสถานะจำลองเท่านั้น</div></section></div>`}
function togglePhoto(i){if(state.picked.includes(i)){if(state.picked.length===1)return toast('กรุณาเลือกรูปอย่างน้อย 1 รูป');state.picked=state.picked.filter(x=>x!==i);if(state.cover===i)state.cover=state.picked[0]}else state.picked.push(i);render()}
function saveDraft(){if(!state.newsTitle.trim()||!state.newsBody.trim())return toast('กรุณากรอกหัวข้อและเนื้อหาข่าว');state.draft=true;persist();toast('บันทึกฉบับร่างแล้ว')}
function previewNews(){if(!state.newsTitle.trim()||!state.newsBody.trim())return toast('กรุณากรอกหัวข้อและเนื้อหาข่าว');modal('Preview ข่าวก่อนเผยแพร่',`<img src="${photos[state.cover]}" alt="รูปปกข่าว"><h2 style="margin-top:18px">${esc(state.newsTitle)}</h2><p class="subtitle">18 กันยายน 2569 · ฝ่ายส่งเสริมสุขภาพ · ชุมชนตัวอย่าง</p><p>${esc(state.newsBody)}</p><div class="notice">${I('info')}เมื่อยืนยัน ข่าวจะปรากฏบนฟีดภายใน และแสดงผลจำลองการส่ง LINE</div>`,btn('กลับไปแก้ไข','closeModal()')+btn('ยืนยันเผยแพร่','publishNews()','check',true))}
function publishNews(){if(!state.roles.includes('เจ้าหน้าที่ประชาสัมพันธ์'))return toast('เฉพาะเจ้าหน้าที่ประชาสัมพันธ์เท่านั้น');state.published=true;state.draft=false;audit(state.newsTitle,'เผยแพร่ข่าว','ฉบับร่าง','เผยแพร่บนฟีดภายใน');persist();closeModal();state.newsTab='เผยแพร่แล้ว';go('news');modal('เผยแพร่ข่าวเรียบร้อยแล้ว',`<div class="choice">${I('check')}<div><h3>เผยแพร่บนฟีดภายใน</h3><p>แสดงข่าวให้ผู้เข้าสู่ระบบแล้ว</p>${badge('เผยแพร่สำเร็จ')}</div></div><div class="choice" style="margin-top:15px">${I('check')}<div><h3>กลุ่ม LINE แจ้งข่าวสำนักฯ</h3><p>สถานะจำลอง • ไม่มีการส่งข้อความจริง</p>${badge('ส่งสำเร็จ (จำลอง)')}</div></div>`,btn('เปิดฟีดข่าว',"closeModal();go('feed')",'arrow',true))}
function admin(){return headline('ดูแลระบบ','จัดการบัญชี สิทธิ์ โครงสร้างหน่วยงาน และการเชื่อมต่อข้อมูล')+tabs(['ผู้ใช้และสิทธิ์','หน่วยงานและหมวดข้อมูล','การเชื่อมต่อ LINE'].map(x=>[x,x]),state.adminTab,'setAdminTab')+(state.adminTab==='ผู้ใช้และสิทธิ์'?`<section class="panel"><div class="table-head"><h2>บัญชีผู้ใช้งาน <span class="muted">${state.users.length} บัญชี</span></h2>${btn('เพิ่มบัญชี','editUser(-1)','plus',true)}</div><div class="table-wrap"><table><thead><tr><th>ชื่อผู้ใช้งาน</th><th>สังกัด</th><th>บทบาท</th><th>สถานะ</th><th></th></tr></thead><tbody>${state.users.map((u,i)=>`<tr><td>${esc(u.name)}</td><td>${esc(u.unit)}</td><td>${u.roles.map(badge).join(' ')}</td><td>${badge(u.active?'ใช้งาน':'ระงับบัญชี')}</td><td>${btn('แก้ไข',`editUser(${i})`,'edit')}</td></tr>`).join('')}</tbody></table></div></section><div class="notice">${I('shield')}บัญชีหนึ่งมีหลายบทบาทได้ • สิทธิ์ผู้ดูแลระบบไม่ทำให้แก้ไขรายงานของทุกคนได้ การแก้รายงานพิจารณาจากเจ้าของรายการและขอบเขตของหัวหน้าฝ่าย</div>`:state.adminTab==='หน่วยงานและหมวดข้อมูล'?`<div class="split"><section class="panel body-pad"><h2>โครงสร้างหน่วยงาน</h2><p class="subtitle">สำนักสาธารณสุขและสิ่งแวดล้อม</p>${units.map((u,i)=>`<div class="choice" style="margin-top:15px;padding:15px">${I('building')}<span style="flex:1">${u}</span><button class="text-btn" onclick="editMaster('unit',${i})">แก้ไข</button></div>`).join('')}<div style="margin-top:20px">${btn('เพิ่มหน่วยงาน',"editMaster('unit',-1)",'plus')}</div></section><section class="panel body-pad"><h2>หมวดข้อมูล / ประเภทงาน</h2>${(state.categories||['ประชุมและอบรม','กิจกรรมส่งเสริมสุขภาพ','เยี่ยมบ้าน']).map((x,i)=>`<div class="choice" style="margin-top:15px;padding:15px"><span style="flex:1">${esc(x)}</span><button class="text-btn" onclick="editMaster('category',${i})">แก้ไข</button></div>`).join('')}<div style="margin-top:20px">${btn('เพิ่มหมวดข้อมูล',"editMaster('category',-1)",'plus')}</div></section></div>`:`<div class="split">${['กลุ่มรับรายงาน','กลุ่มส่งข่าวที่อนุมัติแล้ว'].map((x,i)=>`<section class="panel body-pad"><h2>${x}</h2><div style="margin:20px 0">${badge(state.lineOff?.[i]?'ยกเลิกการเชื่อมต่อ':'เชื่อมต่อแล้ว')}</div><p>${i?'LINE แจ้งข่าวสำนักฯ':'รายงานงานส่งเสริมสุขภาพ'}</p><p class="subtitle">${i?'ส่ง':'รับ'}ข้อมูลล่าสุด: 30 ก.ย. 2569 เวลา ${i?'09:15':'09:30'} น.</p><div style="margin-top:20px">${btn('ตั้งค่าการเชื่อมต่อ',`lineSettings(${i})`,'settings')}</div></section>`).join('')}</div><div class="notice">${I('info')}การเชื่อมต่อแบบจำลอง ไม่มีการใช้ Token หรือส่งข้อมูลไปยัง LINE จริง</div>`)}
function auditPage(){let rows=state.audits.filter(x=>(!state.auditWho||x.who.includes(state.auditWho))&&(!state.auditItem||x.item.includes(state.auditItem))&&(!state.auditDate||x.time.startsWith(state.auditDate)));return headline('ประวัติการแก้ไขข้อมูล','ตรวจสอบการเปลี่ยนแปลงและย้อนกลับไปยังรายการต้นทาง • อ่านอย่างเดียว')+`<div class="filters"><label class="filter">${I('people')}<input placeholder="ค้นหาผู้แก้ไข" value="${esc(state.auditWho||'')}" onchange="state.auditWho=this.value;render()"></label><label class="filter">${I('search')}<input placeholder="ค้นหารายการข้อมูล" value="${esc(state.auditItem||'')}" onchange="state.auditItem=this.value;render()"></label>${select(['ทุกวัน','18 ก.ย. 2569','30 ก.ย. 2569'],state.auditDate||'ทุกวัน',"state.auditDate=this.value==='ทุกวัน'?'':this.value;render()",'calendar')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>วันเวลา</th><th>ผู้แก้ไข</th><th>รายการที่แก้ไข</th><th>ประเภทการเปลี่ยนแปลง</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.time}</td><td>${x.who}</td><td>${esc(x.item)}</td><td>${badge(x.kind)}</td><td>${btn('ดูการเปลี่ยนแปลง',`auditDetail(${state.audits.indexOf(x)})`,'eye')}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">ไม่พบประวัติที่ตรงกับตัวกรอง</div>':''}</div></section>`}
function audit(item,kind,old,next){state.audits.unshift({time:'30 ก.ย. 2569 · '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'})+' น.',who:'สมใจ ใจดี',item,kind,old,next})}
function auditDetail(i){let x=state.audits[i],r=state.rows.find(r=>r.name===x.item);modal('รายละเอียดการเปลี่ยนแปลง',`<p>${esc(x.item)}<br><span class="muted">${x.who} · ${x.time}</span></p><div class="split"><div class="choice"><div><h3>ค่าเดิม</h3><p>${esc(x.old)}</p></div></div><div class="choice selected"><div><h3>ค่าใหม่</h3><p>${esc(x.next)}</p></div></div></div>`,r?btn('เปิดรายการต้นทาง',`closeModal();detail(${r.id})`,'link'):btn('ปิด','closeModal()'))}
function modal(title,body,actions=''){ $('#modal').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${title}</h2><button aria-label="ปิด" onclick="closeModal()">${I('close')}</button></header>${body}<div class="actions">${actions}</div></section></div>`;$('#modal button')?.focus()}
function closeModal(){$('#modal').innerHTML=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function switchRole(){let roles=['เจ้าหน้าที่ปฏิบัติงาน','หัวหน้าฝ่าย','ผู้บริหารสำนัก','เจ้าหน้าที่ประชาสัมพันธ์','ผู้ดูแลระบบ'];modal('บัญชีผู้ใช้และบทบาทสาธิต',`<p>ทดลองหน้าจอและสิทธิ์ตามบทบาท บัญชีเดียวเลือกได้หลายบทบาท</p><form id="roleForm" class="form"><div class="checks">${roles.map(r=>`<label><input type="checkbox" name="roles" value="${r}" ${state.roles.includes(r)?'checked':''}>${r}</label>`).join('')}</div><label>บทบาทเริ่มต้น<select name="primary">${opts(roles,state.role)}</select></label></form><p class="subtitle">สังกัดตัวอย่าง: ฝ่ายส่งเสริมสุขภาพ<br>หัวหน้าฝ่ายรับผิดชอบ: ฝ่ายส่งเสริมสุขภาพ</p>`,btn('ออกจากระบบ',"closeModal();go('login')",'logout')+btn('ใช้บทบาทที่เลือก','applyRole()','check',true))}
function applyRole(){let f=new FormData($('#roleForm'));state.role=f.get('primary');state.roles=f.getAll('roles');if(!state.roles.includes(state.role))state.roles.push(state.role);closeModal();landRole()}
function landRole(){if(state.role==='เจ้าหน้าที่ประชาสัมพันธ์')go('news');else if(state.role==='ผู้ดูแลระบบ')go('admin');else{state.dash=state.role==='หัวหน้าฝ่าย'?'unit':state.role==='เจ้าหน้าที่ปฏิบัติงาน'?'mine':'overview';go('dashboard')}}
function login(){return `<div class="login"><div class="login-art"><div class="brand" style="padding:0;margin-bottom:45px"><div class="brandmark" style="background:#ffffff20">${I('activity')}</div><div><strong>เชื่อมโยง</strong><small style="color:#b4d8cd">KHON KAEN CONNECT</small></div></div><h1>เชื่อมข้อมูลการทำงาน<br>เพื่อสุขภาวะที่ดีของเมือง</h1><p>ระบบบูรณาการข้อมูลและสรุปผลการปฏิบัติงาน<br>สำนักสาธารณสุขและสิ่งแวดล้อม<br>เทศบาลนครขอนแก่น</p><span class="demo" style="align-self:flex-start;margin-top:40px">ข้อมูลจำลอง • เวอร์ชันต้นแบบ</span></div><div class="login-form"><h1>เข้าสู่ระบบ</h1><p class="subtitle" style="margin-bottom:30px">ยินดีต้อนรับสู่พื้นที่การทำงานของคุณ</p><form class="form" onsubmit="loginSubmit(event)"><label>ชื่อผู้ใช้<input name="username" placeholder="ชื่อผู้ใช้" autocomplete="username" required></label><label>รหัสผ่าน<div style="position:relative"><input id="password" name="password" type="password" placeholder="รหัสผ่าน" autocomplete="current-password" required><button type="button" aria-label="แสดงหรือซ่อนรหัสผ่าน" style="position:absolute;right:9px;top:10px" onclick="$('#password').type=$('#password').type==='password'?'text':'password'">${I('eye')}</button></div></label><label>บทบาทสำหรับสาธิต<select name="role">${opts(['เจ้าหน้าที่ปฏิบัติงาน','หัวหน้าฝ่าย','ผู้บริหารสำนัก','เจ้าหน้าที่ประชาสัมพันธ์','ผู้ดูแลระบบ'],state.role)}</select></label><div id="loginError" style="color:#bb544d;font-size:12px" role="alert"></div><button class="btn primary" type="submit">เข้าสู่ระบบ ${I('arrow')}</button></form><div class="notice">${I('info')}บัญชีสาธิต: demo / demo123<br>ระบบนี้ไม่มีการยืนยันตัวตนจริง</div></div></div>`}
function loginSubmit(e){e.preventDefault();let f=new FormData(e.target);if(f.get('username')!=='demo'||f.get('password')!=='demo123'){ $('#loginError').textContent='ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง กรุณาลองใหม่';return}state.role=f.get('role');state.roles=[state.role];landRole()}
function render(){if(['news','editor'].includes(state.page)&&!state.roles.includes('เจ้าหน้าที่ประชาสัมพันธ์'))state.page='dashboard';if(['admin','audit'].includes(state.page)&&!state.roles.includes('ผู้ดูแลระบบ'))state.page='dashboard';const pages={dashboard,library,import:importPage,detail:detailPage,feed,news,editor,admin,audit:auditPage};$('#app').innerHTML=state.page==='login'?login():shell((pages[state.page]||dashboard)());document.title=(state.page==='login'?'เข้าสู่ระบบ':'เชื่อมโยง')+' • เทศบาลนครขอนแก่น'}
function help(){modal('คู่มือทดลองใช้งาน',`<p>เลือกบัญชีมุมขวาบนเพื่อทดลองบทบาทต่าง ๆ</p><p>1. คลังข้อมูล → นำเข้าข้อมูล → เลือกวัตถุประสงค์ → บันทึก<br>2. แดชบอร์ด → กดจำนวนกิจกรรม → เปิดรายละเอียด<br>3. บทบาทประชาสัมพันธ์ → จัดทำข่าว → Preview → ยืนยันเผยแพร่<br>4. บทบาทผู้ดูแลระบบ → ผู้ใช้และสิทธิ์ → แก้ไขบัญชี</p><p>ต้นแบบนี้เก็บการเปลี่ยนแปลงในเบราว์เซอร์ ไม่เชื่อมระบบจริง</p>`,btn('เริ่มใช้งาน','closeModal()','check',true))}
function notifications(){modal('การแจ้งเตือน',`<div class="choice">${I('clock')}<div><h3>มี 5 รายการรอตรวจข้อมูล</h3><p>ฝ่ายส่งเสริมสุขภาพ · กันยายน 2569<br>ยังไม่รวมในยอด 90 กิจกรรม</p></div></div>`,btn('ดูรายการ',"closeModal();state.dash='unit';state.unit=units[0];openSummary('รอตรวจข้อมูล')",'arrow',true))}
function periodInfo(){modal('ขอบเขตข้อมูลสรุป',`<p>ช่วงข้อมูล: 1–30 กันยายน 2569</p><p>ฝ่ายส่งเสริมสุขภาพ 90 กิจกรรม<br>ฝ่ายป้องกันและควบคุมโรค 80 กิจกรรม<br>ฝ่ายบริการสิ่งแวดล้อม 70 กิจกรรม</p><p>รวม 240 กิจกรรม โดยมี 5 รายการของฝ่ายส่งเสริมสุขภาพรอตรวจและไม่รวมในยอดนี้</p><p class="subtitle">กราฟเดือนก่อนหน้าเป็นแนวโน้มจำลอง ไม่มีข้อมูลรายละเอียดรายกิจกรรม</p>`,btn('เข้าใจแล้ว','closeModal()'))}
function sourceModal(){let r=state.rows.find(x=>x.id===state.selected);modal('ต้นฉบับรายงาน',`<span class="badge line">${esc(r.source)}</span><p>${esc(r.name)}<br>${esc(r.date)}<br>${esc(r.area)}</p><p>${esc(r.result)}</p><p>ผู้ปฏิบัติงาน: ${esc(r.workers)}</p><p class="subtitle">ต้นทางแบบจำลอง • ไม่มีลิงก์ไปยังบัญชี LINE จริง</p>`,btn('ปิด','closeModal()'))}
function imageModal(i){modal('ภาพหลักฐาน (ข้อมูลจำลอง)',`<img src="${photos[i]}" alt="ภาพหลักฐานประกอบจำลอง"><p class="subtitle">ภาพประกอบเพื่อสาธิต ไม่ใช่ภาพถ่ายกิจกรรมจริง</p>`)}
function previewDoc(name){let d=state.docs.find(x=>x.name===name);modal('Preview เอกสาร',`<div style="background:#f4f6f7;padding:30px;text-align:center">${I('file')}<h2>${esc(name)}</h2><p>เอกสารตัวอย่างสำหรับค้นหาและอ้างอิง</p><hr style="border:0;border-top:1px solid #ddd"><p>สำนักสาธารณสุขและสิ่งแวดล้อม<br>เทศบาลนครขอนแก่น</p></div><p>หน่วยงาน: ${esc(d?.unit)}<br>ผู้นำเข้า: ${esc(d?.owner)}<br>วันที่นำเข้า: ${d?.date}<br>วัตถุประสงค์: ฝากไฟล์ไว้ค้นหาและอ้างอิง</p><p class="subtitle">ตัวอย่าง Preview • โปรโตไทป์เก็บเฉพาะข้อมูลกำกับไฟล์ ไม่เก็บไฟล์จริง</p>`)}
function readNews(i){let x=state.feedItems[i];modal(x.title,`<img src="${x.img}" alt="รูปข่าวจำลอง"><p class="subtitle">${x.unit} · ${x.date} · ${x.area}</p><p>${esc(x.body)}</p><h3>แกลเลอรีรูปภาพ</h3><div class="evidence">${photos.map((p,j)=>`<button onclick="imageModal(${j})"><img src="${p}" alt="ภาพประกอบ ${j+1}"></button>`).join('')}</div>`)}
function pickReport(){modal('เลือกรายงานต้นทาง',`<div class="choice"><div><h3>ประชุมเครือข่าย อสม.</h3><p>18 กันยายน 2569 · ฝ่ายส่งเสริมสุขภาพ<br>จัดประชุม 1 ครั้ง • ผู้เข้าร่วม 32 คน</p>${badge('พร้อมสรุป')}</div></div>`,btn('เลือกรายงานนี้',"state.manual=true;state.rejected=false;closeModal();go('editor')",'check',true))}
function editUser(i){let u=i<0?{name:'',unit:units[0],roles:[],active:true}:state.users[i];modal(i<0?'เพิ่มบัญชีผู้ใช้งาน':'แก้ไขบัญชีผู้ใช้งาน',`<form id="userForm" class="form"><label>ชื่อ–นามสกุล<input name="name" value="${esc(u.name)}" required></label><label>สังกัด<select name="unit">${opts([...units,'งานบริหารทั่วไป','สำนักสาธารณสุขและสิ่งแวดล้อม'],u.unit)}</select></label><label>บทบาท (เลือกได้หลายบทบาท)</label><div class="checks">${['เจ้าหน้าที่ปฏิบัติงาน','หัวหน้าฝ่าย','ผู้บริหารสำนัก','เจ้าหน้าที่ประชาสัมพันธ์','ผู้ดูแลระบบ'].map(r=>`<label><input type="checkbox" name="roles" value="${r}" ${u.roles.includes(r)?'checked':''}>${r}</label>`).join('')}</div><label>หน่วยงานที่หัวหน้ารับผิดชอบ<select name="responsible">${opts(units,u.responsible||u.unit)}</select></label><label>สถานะบัญชี<select name="active">${opts(['ใช้งาน','ระงับบัญชี'],u.active?'ใช้งาน':'ระงับบัญชี')}</select></label></form>`,btn('ยกเลิก','closeModal()')+btn('บันทึก',`saveUser(${i})`,'check',true))}
function saveUser(i){let form=$('#userForm');if(!form.reportValidity())return;let f=new FormData(form);if(!f.getAll('roles').length)return toast('กรุณาเลือกบทบาทอย่างน้อยหนึ่งบทบาท');let u={name:f.get('name'),unit:f.get('unit'),roles:f.getAll('roles'),responsible:f.get('responsible'),active:f.get('active')==='ใช้งาน'};let old=i<0?'ไม่มีบัญชี':state.users[i].roles.join(', ');if(i<0)state.users.push(u);else state.users[i]=u;audit(u.name,'แก้ไขสิทธิ์',old,u.roles.join(', '));persist();closeModal();render();toast('บันทึกบัญชีและสิทธิ์แล้ว')}
function editMaster(type,i){let list=type==='unit'?units:(state.categories||['ประชุมและอบรม','กิจกรรมส่งเสริมสุขภาพ','เยี่ยมบ้าน']);modal((i<0?'เพิ่ม':'แก้ไข')+(type==='unit'?'หน่วยงาน':'หมวดข้อมูล'),`<form id="masterForm" class="form"><label>ชื่อ<input name="name" value="${esc(i<0?'':list[i])}" required></label></form>`,btn('บันทึก',`saveMaster('${type}',${i})`,'check',true))}
function saveMaster(type,i){if(!$('#masterForm').reportValidity())return;let name=new FormData($('#masterForm')).get('name');let list=type==='unit'?units:(state.categories ||= ['ประชุมและอบรม','กิจกรรมส่งเสริมสุขภาพ','เยี่ยมบ้าน']);let old=list[i]||'ไม่มีข้อมูล';if(i<0)list.push(name);else{list[i]=name;if(type==='unit'){state.rows.forEach(r=>{if(r.unit===old)r.unit=name});state.users.forEach(r=>{if(r.unit===old)r.unit=name})}}audit(name,'แก้ไขข้อมูลตั้งต้น',old,name);persist();closeModal();render();toast('บันทึกข้อมูลแล้ว')}
function lineSettings(i){modal('ตั้งค่าการเชื่อมต่อ LINE',`<p>กลุ่ม: ${i?'LINE แจ้งข่าวสำนักฯ':'รายงานงานส่งเสริมสุขภาพ'}</p><p class="subtitle">การเชื่อมต่อแบบจำลองสำหรับสาธิตเท่านั้น</p>`,btn(state.lineOff?.[i]?'เชื่อมต่อ':'ยกเลิกการเชื่อมต่อ',`state.lineOff ||= {};state.lineOff[${i}]=!state.lineOff[${i}];closeModal();render();toast('อัปเดตสถานะจำลองแล้ว')`,'link',true))}
render();
